<?php require __DIR__.'/bootstrap.php'; require_login(); header('Content-Type: application/json; charset=utf-8');
$action=$_GET['action']??'';
if($action==='notices'){echo json_encode($pdo->query('SELECT id,title,body,published_at FROM notices ORDER BY published_at DESC LIMIT 10')->fetchAll());exit;}
if($action==='events' && $_SERVER['REQUEST_METHOD']==='GET'){echo json_encode(['ok'=>true,'data'=>$pdo->query('SELECT id,title,description,starts_at,ends_at,location,category,event_status FROM events ORDER BY starts_at DESC')->fetchAll()]);exit;}
if($action==='events' && $_SERVER['REQUEST_METHOD']==='POST'){require_admin();verify_csrf();$input=$_POST;$method=$input['method']??'create';if($method==='delete'){$pdo->prepare('DELETE FROM events WHERE id=?')->execute([(int)($input['id']??0)]);echo json_encode(['ok'=>true]);exit;}$title=trim($input['title']??'');$starts=$input['starts_at']??'';if($title===''||$starts===''){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'Title and start time are required.']);exit;}if($method==='update'){$pdo->prepare('UPDATE events SET title=?,starts_at=?,location=? WHERE id=?')->execute([$title,$starts,trim($input['location']??''),(int)($input['id']??0)]);}else{$pdo->prepare('INSERT INTO events(title,starts_at,location,author_id) VALUES(?,?,?,?)')->execute([$title,$starts,trim($input['location']??''),user()['id']]);}echo json_encode(['ok'=>true]);exit;}
if($action==='theme' && $_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$theme=$_POST['theme']==='dark'?'dark':'light';$s=$pdo->prepare('UPDATE users SET theme=? WHERE id=?');$s->execute([$theme,user()['id']]);$_SESSION['user']['theme']=$theme;echo json_encode(['theme'=>$theme]);exit;}
http_response_code(404);echo json_encode(['error'=>'Unknown API action']);
